using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Orbital;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Positional;
using Microsoft.Extensions.DependencyInjection;
namespace Astronomy.MediaFactory.Tests.KnowledgeFoundation.Validation.OrbitalAndPositional;
public sealed class AstronomyOrbitalAndPositionalValidationIntegrationTests { [Fact] public void Aggregate_registration_is_idempotent_and_registers_expected_rules_once() { var services = new ServiceCollection().AddAstronomyOrbitalAndPositionalValidation().AddAstronomyOrbitalAndPositionalValidation(); using var provider = services.BuildServiceProvider(); var registry = provider.GetRequiredService<IAstronomyKnowledgeValidationRuleRegistry>(); var ids = registry.Descriptors.Select(d => d.RuleId).OrderBy(x => x).ToArray(); foreach (var id in new[] { AstronomyOrbitalReferenceContextValidationRule.Id, AstronomyKeplerianElementsValidationRule.Id, AstronomyOrbitalParametersReferenceContextValidationRule.Id, AstronomyOrbitalParametersValidationRule.Id, AstronomySpatialReferenceContextValidationRule.Id, AstronomyPositionValueValidationRule.Id, AstronomyAngularPositionValidationRule.Id, AstronomySphericalPositionValidationRule.Id, AstronomyCartesianPositionValidationRule.Id }) Assert.Equal(1, ids.Count(x => x == id)); } [Fact] public void Real_payloads_validate_through_typed_validator() { var services = new ServiceCollection().AddAstronomyOrbitalAndPositionalValidation(); using var provider = services.BuildServiceProvider(); var validator = provider.GetRequiredService<IAstronomyTypedKnowledgeValidator>(); Assert.True(validator.Validate(OrbitalPositionalValidationFixture.ValidKeplerian(), OrbitalPositionalValidationFixture.Context()).IsValid); Assert.True(validator.Validate(OrbitalPositionalValidationFixture.ValidParameters(), OrbitalPositionalValidationFixture.Context()).IsValid); Assert.True(validator.Validate(OrbitalPositionalValidationFixture.CartesianPayload(), OrbitalPositionalValidationFixture.Context()).IsValid); } [Fact] public void Minimum_severity_filtering_works() { var services = new ServiceCollection().AddAstronomyOrbitalAndPositionalValidation(); using var provider = services.BuildServiceProvider(); var validator = provider.GetRequiredService<IAstronomyTypedKnowledgeValidator>(); var payload = new Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Orbital.AstronomyKeplerianElementsPayload(new("typed.orbital.keplerian-elements.v1"), OrbitalPositionalValidationFixture.OrbitalContext(), [OrbitalPositionalValidationFixture.Element(Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Orbital.AstronomyKeplerianElementType.SemiMajorAxis, Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Measurements.AstronomyMeasurementDimension.Distance)]); var result = validator.Validate(payload, new AstronomyKnowledgeValidationContext(new AstronomyKnowledgeValidationRunId("strict"), new DateTimeOffset(2026,1,1,0,0,0,TimeSpan.Zero), minimumSeverity: AstronomyKnowledgeValidationSeverity.Error)); Assert.Empty(result.Issues.Where(i => i.Severity < AstronomyKnowledgeValidationSeverity.Error)); } }